    "careers-r1-title": "Site Restoration Volunteer",
    "careers-r1-hook": "Work shoulder to shoulder with local masons to clear, clean, and help conserve a historic site. No experience needed, just care and willing hands.",
    "careers-view": "View role →",
    "careers-lbl-do": "What you'll do:",
    "careers-r1-do": "Clear debris, support conservation work under a steward's direction, and help protect what's left of the site.",
    "careers-lbl-need": "What we need:",
    "careers-r1-need": "To be 18 or older for on-site work, basic fitness, and respect for the place and the people.",
    "careers-apply-btn": "Apply for this role",
    "careers-r2-loc": "Remote",
    "careers-r2-time": "2 to 4 hrs/week",
    "careers-r2-title": "Archive & Memory Volunteer",
    "careers-r2-hook": "Help digitize the photos, documents, and oral histories that tie a site to the people who remember it.",
    "careers-r2-do": "Scan and label materials, transcribe interviews, and help organize a site's living record.",
    "careers-r2-need": "Patience, an eye for detail, and a reliable internet connection. A second language is a plus.",
    "careers-r3-loc": "Remote",
    "careers-r3-time": "Flexible",
    "careers-r3-title": "Translation Volunteer",
    "careers-r3-hook": "Keep Levoila's words true across five languages, so no community is spoken about in a language it can't read.",
    "careers-r3-do": "Review and refine translations of the site and materials in English, French, Haitian Creole, Spanish, or Portuguese.",
    "careers-r3-need": "Native fluency in at least one of these languages and a feel for tone, not just words.",
    "careers-tag-staff": "STAFF",
    "careers-r4-loc": "On-site, Haiti",
    "careers-r4-time": "Per project",
    "careers-r4-title": "Lead Heritage Architect",
    "careers-r4-hook": "Design and direct the restoration of a national monument to the standard history deserves.",
    "careers-r4-do": "Set the restoration approach to UNESCO standards, direct the conservation team, and protect every original detail.",
    "careers-r4-need": "Real heritage or conservation architecture experience and the judgment to make hard calls on a fragile site.",
    "careers-r5-loc": "Frisco, TX or Remote",
    "careers-r5-time": "Full-time",
    "careers-r5-title": "Operations Manager",
    "careers-r5-hook": "Run the day-to-day across countries, vendors, logistics, the calendar, and the public ledger, so the work never stalls.",
    "careers-r5-do": "Coordinate vendors and logistics across time zones, keep the budget and calendar honest, and support every site team.",
    "careers-r5-need": "Strong operations instincts, calm under pressure, and comfort working across languages and borders.",
    "careers-r6-loc": "Remote",
    "careers-r6-time": "Part-time",
    "careers-r6-title": "Grants & Partnerships Writer",
    "careers-r6-hook": "Win the funding that turns plans into scaffolding. Tell Levoila's story to the foundations and institutions that can back it.",
    "careers-r6-do": "Research funders, write proposals and reports, and help build long-term institutional partnerships.",
    "careers-r6-need": "A strong, clear writer with grant or fundraising experience, heritage or international work a plus.",
    "careers-r7-loc": "Remote",
    "careers-r7-time": "Part-time",
    "careers-r7-title": "People & HR Coordinator",
    "careers-r7-hook": "Be the human heart of how Levoila welcomes people, working alongside our HR assistant to make every arrival feel like a homecoming.",
    "careers-r7-do": "Review applications, make hiring decisions with managers, and own the quality of onboarding for every group.",
    "careers-r7-need": "HR or people-operations experience, warmth, fairness, and care with sensitive information.",
    "careers-tag-steward": "STEWARD",
    "careers-r8-loc": "In-country, Haiti",
    "careers-r8-time": "Ongoing appointment",
    "careers-r8-title": "Country Steward, Haiti",
    "careers-r8-hook": "Carry Levoila's name in your community. Hold the relationships, oversee the sites, and answer for every dollar on the public ledger.",
    "careers-r8-do": "Represent Levoila to communities and authorities, oversee local sites and budget, and report every month.",
    "careers-r8-need": "Deep local trust and references, sound judgment, and a commitment to transparency. Nominations welcome.",
    "careers-r9-loc": "In-country",
    "careers-r9-time": "Fixed term",
    "careers-r9-title": "Heritage Fellow",
    "careers-r9-hook": "For an emerging local leader: a term to run a real project under a steward's mentorship, and a path into stewardship itself.",
    "careers-r9-do": "Lead a defined project on a site, learn the work end to end, and grow into a larger role.",
    "careers-r9-need": "Energy, integrity, roots in the community, and the desire to lead. Formal experience is not required.",
    "careers-tag-board": "BOARD",
    "careers-r10-loc": "Remote",
    "careers-r10-time": "Quarterly + committee",
    "careers-r10-title": "Board Member",
    "careers-r10-hook": "Govern the trust. Bring expertise, heritage, law, finance, or the countries we serve, and the judgment to hold us to our word.",
    "careers-r10-do": "Provide fiduciary oversight, shape strategy, and hold Levoila accountable to its mission and its ledger.",
    "careers-r10-need": "Senior expertise in a relevant field, integrity, and the time to govern seriously. Most members are invited or nominated.",
    "careers-r11-loc": "Remote",
    "careers-r11-time": "Light commitment",
    "careers-r11-title": "Advisory Council Member",
    "careers-r11-hook": "Lend your voice and expertise without fiduciary duty, a way for respected people to help steer the work.",
    "careers-r11-do": "Advise on strategy and your area of expertise, and open doors where you can.",
    "careers-r11-need": "Standing in your field and genuine belief in the mission. A few hours a quarter.",
