    "newgen-us-5-desc": "Recruter de nouveaux Stewards et rallier les petits dons.",
    "newgen-us-6-role": "CORPS DES LANGUES & TRADUCTION",
    "newgen-us-6-desc": "Traduire nos contenus en français, kreyòl, espagnol et portugais.",
    "newgen-us-7-role": "HÔTE D'ÉVÉNEMENTS CULTURELS",
    "newgen-us-7-desc": "Organiser des soirées culturelles, des panels et des projections pour la diaspora.",
    "newgen-us-8-role": "CHERCHEUR EN PATRIMOINE",
    "newgen-us-8-desc": "Rechercher les sites, l'histoire et les familles derrière les murs.",
    "newgen-us-9-role": "BÉNÉVOLE TECH & INNOVATION",
    "newgen-us-9-desc": "Construire les outils, sites et données qui font avancer la mission.",
    "newgen-ht-1-role": "CONTEUR DU SITE · KONTÈ",
    "newgen-ht-1-desc": "Documenter les sites et ceux qui les restaurent.",
    "newgen-ht-2-role": "AVANT-GARDE DES RÉSEAUX SOCIAUX",
    "newgen-ht-2-desc": "Partager le travail depuis le terrain, en temps réel.",
    "newgen-ht-3-role": "AMBASSADEUR SCOLAIRE",
    "newgen-ht-3-desc": "Porter la mission dans les lycées et les universités.",
    "newgen-ht-4-role": "CAPITAINE DU SERVICE COMMUNAUTAIRE",
    "newgen-ht-4-desc": "Mener des journées de service dans les villes autour de nos sites.",
    "newgen-ht-5-role": "JEUNE RECRUTEUR DE STEWARDS",
    "newgen-ht-5-desc": "Amener votre génération dans la communauté des Stewards.",
    "newgen-ht-6-role": "GUIDE PATRIMONIAL EN FORMATION",
    "newgen-ht-6-desc": "Apprendre à guider les visiteurs sur nos sites restaurés.",
    "newgen-ht-7-role": "RESPONSABLE ÉVÉNEMENTS & SPECTACLES",
    "newgen-ht-7-desc": "Présenter musique, art et programmes commémoratifs sur site.",
    "newgen-ht-8-role": "GARDIEN DE LA MÉMOIRE · ARCHIVES",
    "newgen-ht-8-desc": "Recueillir des récits oraux et protéger la mémoire locale.",
    "newgen-ht-9-role": "BÉNÉVOLE TECH & INNOVATION",
    "newgen-ht-9-desc": "Apporter des compétences numériques au travail patrimonial.",
