    "home-call-eyebrow": "APÈL LA · NAN SENK LANG",
    "home-call-tagline": "\"Gouvènman yo te bliye. Lemonn sonje. Byenvini nan Levoila.\"",
    "about-eyebrow": "KONSÈNAN LEVOILA",
    "about-h1": "Moun ki dèyè mouvman an.",
    "about-tab-founder": "Fondatè",
