    "nominate-ph-residence": "ex.: Brasil",
    "nominate-submit": "Enviar Indicação",
    "nominate-disclaimer": "Ao enviar, você confirma que as informações são precisas. As indicações são publicadas e analisadas pela comunidade de Curadoria.",
    "nominate-next-eyebrow": "O QUE ACONTECE A SEGUIR",
    "nominate-next-1": "Sua indicação é publicada em até 7 dias.",
    "nominate-next-2": "Os Guardiões analisam e debatem no fórum global.",
    "nominate-next-3": "Na próxima Assembleia Trimestral, os Guardiões votam em quais locais assumir.",
    "nominate-next-4": "Os locais selecionados entram na negociação do Pacto de Soberania.",
    "nominate-next-5": "Você será creditado como o indicador e convidado para a Grande Abertura.",
    "vote-eyebrow": "ASSEMBLEIA TRIMESTRAL · Q3 2026",
    "vote-h1": "O mundo escolhe o que salvar a seguir.",
    "vote-intro": "Seis locais estão em votação neste trimestre. Os Guardiões podem distribuir seu peso de voto entre múltiplos locais. Os dois primeiros entram no ciclo de negociação do Pacto de Soberania.",
    "vote-window-label": "ENCERRAMENTO DA VOTAÇÃO",
    "vote-window-val": "14 dias · 6 horas · 23 minutos",
    "vote-weight-label": "SEU PESO DE VOTO",
    "vote-weight-val": "100 votos (Guardião Ouro)",
    "vote-current-label": "VOTOS ATUAIS",
    "vote-allocate": "Distribuir Votos",
    "vote-1-country": "EGITO · INDICADO POR A. ELDESSOUKY",
    "vote-1-name": "Aqueduto do Velho Cairo",
    "vote-1-body": "Um aqueduto mameluco do século XIV. Trechos desabaram em 2025 sem qualquer resposta do governo. A estrutura é pressionada por ocupações informais.",
    "vote-1-tally": "12.488 de 1.203 Guardiões",
    "vote-2-country": "GANA · INDICADO POR K. ASANTE",
    "vote-2-name": "São Jorge da Mina (Elmina Castle)",
    "vote-2-body": "Uma fortaleza portuguesa do século XV no Golfo da Guiné. Local UNESCO. Um marco sagrado e doloroso do tráfico transatlântico de escravizados.",
    "vote-2-tally": "10.221 de 987 Guardiões",
    "vote-3-country": "ETIÓPIA · INDICADO POR S. GIRMA",
    "vote-3-name": "Estabilização do Teto de Bet Maryam",
    "vote-3-body": "Uma das onze igrejas monolíticas escavadas na rocha em Lalibela. As coberturas instaladas pela UNESCO falharam; o teto exige intervenção imediata.",
    "vote-3-tally": "9.114 de 902 Guardiões",
    "vote-4-country": "MÉXICO · INDICADO POR R. VARGAS",
    "vote-4-name": "Plataformas Externas de Tlatelolco",
    "vote-4-body": "Cidade gêmea asteca de Tenochtitlan. As plataformas externas estão sem vigilância e são usadas à noite para aglomerações não autorizadas.",
    "vote-4-tally": "6.830 de 712 Guardiões",
    "vote-5-country": "TANZÂNIA · INDICADO POR A. MWANGI",
    "vote-5-name": "Estações de Caravanas da Cidade Antiga de Bagamoyo",
    "vote-5-body": "Porto de caravanas e do tráfico escravagista na África Oriental. Estruturas de pedra de coral desmoronando no mar.",
    "vote-5-tally": "4.902 de 530 Guardiões",
    "vote-6-country": "JORDÂNIA · INDICADO POR L. SAID",
    "vote-6-name": "Conservação dos Túmulos Laterais de Petra",
    "vote-6-body": "Os túmulos nos cânions secundários de Petra estão sendo erodidos por enchentes repentinas e pelo fluxo de turistas sem caminhos delimitados.",
    "vote-6-tally": "3.716 de 401 Guardiões",
